63	namespace comdare::diplomarbeit::messung_driver::v32::antrieb {
64	
65	namespace cmd   = ::comdare::cache_engine::builder::commands;
66	namespace comp  = ::comdare::cache_engine::compositions;
67	namespace strat = ::comdare::diplomarbeit::messung_driver::v32::strategy;
68	namespace kat   = ::comdare::diplomarbeit::messung_driver::v32::katalog;
69	namespace cx    = ::comdare::builder::xml;
70	namespace tlz   = ::comdare::cache_engine::thesis_lazy;
71	
72	using strat::MergeStrategy;
73	
74	/// EnumerationMode -- <metadata><mode> (defined|full|full_sampled). Steuert die ENUMERATIONS-BREITE je Phase
75	/// (wie viele OP-Typen gemessen werden); ORTHOGONAL zur Phase (die den Kompositionalen Join = Merge waehlt).
76	enum class EnumerationMode { Defined, Full, FullSampled };
77	
78	/// parse_enumeration_mode -- <metadata><mode>-Token -> EnumerationMode. Unbekannt/leer -> Defined (sicherer Default).
79	[[nodiscard]] inline EnumerationMode parse_enumeration_mode(std::string_view mode) noexcept {
80	    if (mode == "full") return EnumerationMode::Full;
81	    if (mode == "full_sampled") return EnumerationMode::FullSampled;
82	    return EnumerationMode::Defined;
83	}
84	
85	/// merge_strategy_from_name -- der String->Enum-Roundtrip zur validate-Seite (tlz::merge_strategy_name ist
86	/// Enum->String). Single-Source der 3 Werte = tlz::kExperimentMergeStrategies (validate_profile.hpp), KEIN
87	/// dupliziertes Enum. nullopt bei unbekanntem Namen (validate_experiment_profile hat das i.d.R. schon gefangen).
88	[[nodiscard]] inline std::optional<MergeStrategy> merge_strategy_from_name(std::string_view name) {
89	    for (auto const s : tlz::kExperimentMergeStrategies) {
90	        if (tlz::merge_strategy_name(s) == name) { return s; }
91	    }
92	    return std::nullopt;
93	}
94	
95	/// PhaseCompositions<S> -- die realen Katalog-Kompositionen je MergeStrategy (Policy-Based Design, compile-time).
96	/// EE-A ist STETS die CE-SOTA-Baseline (HotComposition, Stufe1_CeOnly); EE-B ist die Phasen-Komposition:
97	///   Stufe1_CeOnly           -> HotComposition                   (Baseline gegen Baseline: erwarteter Tie)
98	///   Stufe2_PrueflingReplace -> HotPrtStufe2ReplaceComposition   (PRT ersetzt den path_compression-Slot)
99	///   Stufe3_FullJoin         -> HotPrtStufe3FullJoinComposition  (non-redundante Union CE + Pruefling)
100	template <MergeStrategy S>
101	struct PhaseCompositions;
102	
103	template <>
104	struct PhaseCompositions<MergeStrategy::Stufe1_CeOnly> {
105	    using EngineA = comp::HotComposition;
106	    using EngineB = comp::HotComposition;
107	};
108	template <>
109	struct PhaseCompositions<MergeStrategy::Stufe2_PrueflingReplace> {
110	    using EngineA = comp::HotComposition;
111	    using EngineB = comp::HotPrtStufe2ReplaceComposition;
112	};
113	template <>
114	struct PhaseCompositions<MergeStrategy::Stufe3_FullJoin> {
115	    using EngineA = comp::HotComposition;
116	    using EngineB = comp::HotPrtStufe3FullJoinComposition;
117	};
118	
119	/// to_permutation_outcome -- KatalogPermutationOutcome (INC-F) -> v32::PermutationOutcome (Exporter-Eingabe).
120	/// Reine Feld-Projektion (beide tragen cmd::ExecutionResult + Verdict + welch/throughput); die Pruefdock-
121	/// Konformitaets-Felder werden nicht in die 12-Spalten-CSV projiziert (der Exporter kennt sie nicht).
122	[[nodiscard]] inline PermutationOutcome to_permutation_outcome(kat::KatalogPermutationOutcome const& ko) {
123	    PermutationOutcome po;
124	    po.axis_id          = ko.axis_id;
125	    po.variant_name     = ko.variant_name;
126	    po.ee_a_result      = ko.ee_a_result;
127	    po.ee_b_result      = ko.ee_b_result;
128	    po.verdict          = ko.verdict;
129	    po.welch_p_value    = ko.welch_p_value;
130	    po.throughput_ratio = ko.throughput_ratio;
131	    return po;
132	}
133	
134	/// op_labels_for_mode -- die je-Phase enumerierte OP-Typ-Liste aus dem Profil, gefiltert nach EnumerationMode:
135	///   Defined     = genau der erste deklarierte OP-Typ (1 Permutation je Phase -> stets >= 1 Verdikt je Phase).
136	///   Full        = alle deklarierten OP-Typen.
137	///   FullSampled = jeder zweite (mindestens 1).
138	/// Leeres <op_types> -> Fallback "OP-1" (auch dann >= 1 Permutation je Phase).
139	[[nodiscard]] inline std::vector<std::string> op_labels_for_mode(std::vector<std::string> const& op_types,
140	                                                                 EnumerationMode                 mode) {
141	    std::vector<std::string> const source = op_types.empty() ? std::vector<std::string>{"OP-1"} : op_types;
142	    std::vector<std::string>       out;
143	    switch (mode) {
144	        case EnumerationMode::Defined: out.push_back(source.front()); break;
145	        case EnumerationMode::Full: out = source; break;
146	        case EnumerationMode::FullSampled:
147	            for (std::size_t i = 0; i < source.size(); i += 2) { out.push_back(source[i]); }
148	            break;
149	    }
150	    if (out.empty()) { out.push_back(source.front()); }
151	    return out;
152	}
153	
154	/// drive_phase<S> -- treibt EINE Phase (compile-time MergeStrategy S) ueber alle enumerierten OP-Typen. Je
155	/// OP-Typ eine reale Katalog-Permutation (INC-F): EE-A/EE-B = PhaseCompositions<S>, distinktes Seed je
156	/// (phase,op) -> unabhaengige Mess-Laeufe. Ergebnisse akkumulieren in den MessreiheReport (Wins/Ties-Bilanz).
157	/// Der Concept-Guard (INC-E) erzwingt die vollstaendige Phase-Strategy-API zur Compile-Zeit.
158	template <MergeStrategy S>
159	inline void drive_phase(MessreiheReport& report, cx::ExperimentPhase const& phase,
160	                        std::vector<std::string> const& op_labels, cmd::Workload base, std::size_t phase_index) {
161	    using PhaseStrat = strat::PhaseStrategyFor<S>;
162	    static_assert(strat::ExperimentPhaseStrategy<PhaseStrat>, "INC-E Concept-Guard: Phase-Strategy unvollstaendig");
163	    using EngineA = typename PhaseCompositions<S>::EngineA;
164	    using EngineB = typename PhaseCompositions<S>::EngineB;
165	
166	    std::string const axis_id = std::string{PhaseStrat::phase_name()}; // == merge-Name (stabile Phasen-Identitaet)
167	    std::size_t       op_idx  = 0;
168	    for (auto const& op_label : op_labels) {
169	        cmd::Workload wl = base;
170	        (void)apply_op_type_token(op_label, wl);                     // OP-Typ -> WorkloadKind (op_type_filter)
171	        wl.seed = base.seed + phase_index * 997U + (op_idx++) * 31U; // distinktes Seed je (phase,op) -> unabhaengig
172	
173	        std::string const variant = phase.name + "@" + op_label;
174	        auto const        ko      = kat::execute_one_permutation_katalog<EngineA, EngineB>(axis_id, variant, wl);
175	
176	        switch (ko.verdict) {
177	            case cmd::CompareEngineCommand::Verdict::EE_A_Wins: ++report.ee_a_wins; break;
178	            case cmd::CompareEngineCommand::Verdict::EE_B_Wins: ++report.ee_b_wins; break;
179	            case cmd::CompareEngineCommand::Verdict::Tie: ++report.ties; break;
180	            default: break;
181	        }
182	        ++report.total_variants;
183	        report.outcomes.push_back(to_permutation_outcome(ko));
184	    }
185	}
186	
187	/// dispatch_phase -- der EINMALIGE Runtime->Compile-Time-Switch (Enumerations-Zeit, KEIN Hot-Path): loest den
188	/// phase.merge-String auf die MergeStrategy-Enum auf und ruft drive_phase<S> mit der compile-time gewaehlten
189	/// Strategy + Komposition. false = unbekannte Merge-Strategie (validate_experiment_profile faengt das zuvor ab).
190	[[nodiscard]] inline bool dispatch_phase(MessreiheReport& report, cx::ExperimentPhase const& phase,
191	                                         std::vector<std::string> const& op_labels, cmd::Workload const& base,
192	                                         std::size_t phase_index) {
193	    auto const s = merge_strategy_from_name(phase.merge);
194	    if (!s) { return false; }
195	    switch (*s) {
196	        case MergeStrategy::Stufe1_CeOnly:
197	            drive_phase<MergeStrategy::Stufe1_CeOnly>(report, phase, op_labels, base, phase_index);
198	            return true;
199	        case MergeStrategy::Stufe2_PrueflingReplace:
200	            drive_phase<MergeStrategy::Stufe2_PrueflingReplace>(report, phase, op_labels, base, phase_index);
201	            return true;
202	        case MergeStrategy::Stufe3_FullJoin:
203	            drive_phase<MergeStrategy::Stufe3_FullJoin>(report, phase, op_labels, base, phase_index);
204	            return true;
205	    }
206	    return false;
207	}
208	
209	/// run_experiment_profile -- der reine Antrieb (INC-G): je Phase des validierten Profils die realen Katalog-
210	/// Tiers treiben und in einen MessreiheReport akkumulieren. KEIN Datei-IO (das ist INC-H/execute_messreihe).
211	[[nodiscard]] inline MessreiheReport run_experiment_profile(cx::ExperimentProfile const& profile,
212	                                                            EnumerationMode              mode) {
213	    MessreiheReport report;
214	    auto const      start = std::chrono::steady_clock::now();
215	
216	    cmd::Workload base;
217	    base.record_count    = 2000; // moderat: genug Samples fuer Welch, Test < TIMEOUT (== INC-F-Gate)
218	    base.operation_count = 2000;
219	    base.seed            = 42;
220	
221	    auto const op_labels = op_labels_for_mode(profile.op_types, mode);
222	
223	    report.total_axes       = profile.phases.size();
224	    std::size_t phase_index = 0;
225	    for (auto const& phase : profile.phases) { (void)dispatch_phase(report, phase, op_labels, base, phase_index++); }
226	
227	    report.total_elapsed = std::chrono::steady_clock::now() - start;
228	    return report;
229	}
230	
231	/// substitute_date -- ersetzt jedes ${date}-Token in einem <output>-Pfad durch das aktuelle Datum (YYYYMMDD).
232	/// Erlaubt den in der Golden-Instanz genutzten _runs/${date}/... -Pfad ohne externe Shell-Expansion.
233	[[nodiscard]] inline std::string substitute_date(std::string path) {
234	    constexpr std::string_view token = "${date}";
235	    if (path.find(token) == std::string::npos) { return path; }
236	    std::time_t const now = std::time(nullptr);
237	    std::tm           tm{};
238	#if defined(_WIN32)
239	    localtime_s(&tm, &now);
240	#else
241	    localtime_r(&now, &tm);
242	#endif
243	    char buf[16] = {};
244	    std::strftime(buf, sizeof(buf), "%Y%m%d", &tm);
245	    for (auto p = path.find(token); p != std::string::npos; p = path.find(token, p)) {
246	        path.replace(p, token.size(), buf);
247	    }
248	    return path;
249	}
250	
251	/// execute_messreihe -- der OFFIZIELLE Einstieg (INC-G+H): parse (INC-D) -> validate (INC-D) -> Antrieb
252	/// (run_experiment_profile) -> Export (INC-H: CSV + TikZ nach <output>). Rueckgabe int (Test-Kompat):
253	///   0 = ok · 2 = parse-Fehler · 3 = validate-Fehler · 4 = leerer Report · 5 = Export-Fehler.
254	/// registry_dir wird leer gelassen (rein strukturelle Validierung); der volle Registry-Abgleich (4)+(5) ist
255	/// Sache der Fassade, die das Registry-Verzeichnis kennt (analog test_experiment_parser::make_registry_dir).
256	[[nodiscard]] inline int execute_messreihe(std::string_view config_xml, std::string_view mode = "defined") {
257	    cx::XmlConfigParser const parser;
258	    auto const                profile = parser.parse_experiment_profile(std::filesystem::path{std::string{config_xml}});
259	    if (!profile) {
260	        std::cerr << "[INC-G] parse_experiment_profile fehlgeschlagen: " << config_xml << "\n";
261	        return 2;
262	    }
263	
264	    auto const vr = tlz::validate_experiment_profile(*profile); // registry_dir leer -> strukturelle Validierung
265	    if (!vr.ok) {
266	        std::cerr << "[INC-G] validate_experiment_profile: " << vr.errors.size() << " Fehler.\n";
267	        for (auto const& e : vr.errors) { std::cerr << "  [FEHLER] " << e << "\n"; }
268	        return 3;
269	    }
270	
271	    MessreiheReport const report = run_experiment_profile(*profile, parse_enumeration_mode(mode));
272	    if (report.outcomes.empty()) {
273	        std::cerr << "[INC-G] leerer MessreiheReport (keine Permutation getrieben).\n";
274	        return 4;
275	    }
276	
277	    // INC-H: Export CSV + TikZ nach den <output>-Pfaden der Experiment-XML (${date} aufgeloest, Parent-Dirs
278	    // angelegt). Der <binary_path> wird bewusst NICHT geschrieben -- der MessreiheReportExporter emittiert
279	    // ausschliesslich CSV + TikZ; der binaere Mess-Record-Pfad ist Sache des Voll-Pipeline-Writers (nicht INC-H).
280	    MessreiheReportExporter const ex;
281	    std::filesystem::path const   csv_path = substitute_date(profile->output.csv_path);
282	    std::filesystem::path const   tex_path = substitute_date(profile->output.latex_path);
283	
284	    std::error_code ec;
285	    if (csv_path.has_parent_path()) { std::filesystem::create_directories(csv_path.parent_path(), ec); }
286	    if (tex_path.has_parent_path()) { std::filesystem::create_directories(tex_path.parent_path(), ec); }
287	
288	    auto const cs = ex.write_csv(report, csv_path);
289	    auto const ts = ex.write_tikz_summary(report, tex_path);
290	    if (!cs.ok() || !ts.ok()) {
291	        std::cerr << "[INC-H] Export-Fehler: csv=" << cs.message << " tikz=" << ts.message << "\n";
292	        return 5;
293	    }
294	
295	    std::cout << "[INC-G+H] execute_messreihe ok: " << report.outcomes.size() << " Permutationen -> "
296	              << csv_path.string() << " + " << tex_path.string() << "\n";
297	    return 0;
298	}
